/bin/bash -lc "node <<'NODE'
const fs = require('fs');
const crypto = require('crypto');
const path = "'`${process.env.HOME}/.config/google-chrome/Default/Bookmarks`;
const backup = `${path}.codex-backup-${new Date().toISOString().replace(/[:.]/g, '"'-')}"'`;
fs.copyFileSync(path, backup);
const data = JSON.parse(fs.readFileSync(path, '"'utf8'));
const roots = data.roots;
const bar = roots.bookmark_bar;
bar.children = Array.isArray(bar.children) ? bar.children : [];

const chromeTime = () => String(Date.now() * 1000 + 11644473600000000);
const walk = (node, out = []) => {
  out.push(node);
  if (Array.isArray(node.children)) node.children.forEach(child => walk(child, out));
  return out;
};
const allNodes = Object.values(roots).flatMap(root => walk(root));
let nextId = Math.max(...allNodes.map(n => Number(n.id)).filter(Number.isFinite)) + 1;
const now = chromeTime();

const entries = [
  ['Linxi \"Jim\" Fan', 'https://jimfan.me/'],
  ['De-An Huang', 'https://ai.stanford.edu/~dahuang/'],
  ['Yuke Zhu', 'https://yukezhu.me/'],
  ['Anima Anandkumar', 'https://tensorlab.cms.caltech.edu/users/anima/index.html'],
];

let folder = bar.children.find(child => child.type === 'folder' && child.name === 'Liked Authors');
if ("'!folder) {
  folder = {
    children: [],
    date_added: now,
    date_last_used: '"'0',
    date_modified: now,
    guid: crypto.randomUUID(),
    id: String(nextId++),
    name: 'Liked Authors',
    type: 'folder',
  };
  bar.children.push(folder);
}
folder.children = Array.isArray(folder.children) ? folder.children : [];

for (const [name, url] of entries) {
  const existing = folder.children.find(child => child.type === 'url' && (child.url === url || child.name === name));
  if (existing) {
    existing.name = name;
    existing.url = url;
    existing.date_last_used = existing.date_last_used || '0';
    continue;
  }
  folder.children.push({
    date_added: now,
    date_last_used: '0',
    guid: crypto.randomUUID(),
    id: String(nextId++),
    name,
    type: 'url',
    url,
  });
}
folder.date_modified = now;
bar.date_modified = now;

function checksum(roots) {
  const digest = crypto.createHash('md5');
  const update = node => {
    digest.update(node.id, 'ascii');
    digest.update(node.name, 'utf16le');
    if (node.type === 'url') {
      digest.update(Buffer.from('url'));
      digest.update(node.url, 'ascii');
    } else {
      digest.update(Buffer.from('folder'));
      for (const child of node.children || []) update(child);
    }
  };
  for (const key of ['bookmark_bar', 'other', 'synced']) update(roots[key]);
  return digest.digest('hex');
}
data.checksum = checksum(roots);
fs.writeFileSync(path, JSON.stringify(data, null, 3) + '\\n');
console.log("'`Updated ${path}`);
console.log(`Backup ${backup}`);
NODE'

